import sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8", errors="replace")
sys.path.insert(0, r"C:\Projects\NSCM\_artifacts\_diagnostics")
from ora import conn_info
import oracledb
u,p,d = conn_info()
con = oracledb.connect(user=u,password=p,dsn=d); cur=con.cursor()
cur.execute("ALTER SESSION SET CURRENT_SCHEMA=SCM_MGR")
cur.execute("ALTER SESSION SET NLS_DATE_FORMAT='YYYY-MM-DD HH24:MI:SS'")
def show(title, sql, **b):
    try:
        cur.execute(sql, b); cols=[c[0] for c in cur.description]; rows=cur.fetchall()
    except Exception as e:
        print(f"\n## {title} ERROR {e}"); return
    print(f"\n## {title} ({len(rows)} rows)"); print(" | ".join(cols))
    for r in rows: print(" | ".join("" if v is None else str(v).replace("\n","\n")[:200] for v in r))
show("GRANTS PKG_SCP0100", "SELECT GRANTEE,PRIVILEGE,GRANTABLE FROM ALL_TAB_PRIVS WHERE TABLE_SCHEMA='SCM_MGR' AND TABLE_NAME='PKG_SCP0100'")
show("GRANTS GT_SCP0100", "SELECT TABLE_NAME,GRANTEE,LISTAGG(PRIVILEGE,',') WITHIN GROUP (ORDER BY PRIVILEGE) PRIVS FROM ALL_TAB_PRIVS WHERE TABLE_SCHEMA='SCM_MGR' AND TABLE_NAME LIKE 'GT_SCP0100%' GROUP BY TABLE_NAME,GRANTEE ORDER BY 1")
show("SYNONYMS", "SELECT OWNER,SYNONYM_NAME,TABLE_OWNER,TABLE_NAME FROM ALL_SYNONYMS WHERE TABLE_NAME IN ('PKG_SCP0100') OR SYNONYM_NAME IN ('SCM_MST_ITEM_SN')")
show("GTT FLAGS", "SELECT TABLE_NAME,TEMPORARY,DURATION,NUM_ROWS FROM ALL_TABLES WHERE OWNER='SCM_MGR' AND (TABLE_NAME LIKE 'GT_SCP0100%' OR TABLE_NAME LIKE '%TBLSCP0100%') ORDER BY 1")
show("FN deps created", "SELECT OBJECT_NAME,OBJECT_TYPE,STATUS,CREATED,LAST_DDL_TIME FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND OBJECT_NAME IN ('FN_CHAR_TO_DATE','FN_GET_REPORT_USER_COLUMNS','FN_SPLITSTRING','SCP_PLAN_VERSION_V','SCM_MST_ITEM_SN','SCP_RPT_GLOBAL_PSI_MD_DETAIL_MM','SCP_RPT_GLOBAL_PSI_MD_DETAIL_WW','SCP_RPT_GLOBAL_PSI_MD_MM','SCP_RPT_GLOBAL_PSI_MD_WW','SCP_PLN_INTERFACE_YN','SCP_MST_FINAL_ITEM') ORDER BY 1")
show("FN_GET_REPORT_USER_COLUMNS dependents", "SELECT OWNER,NAME,TYPE FROM ALL_DEPENDENCIES WHERE REFERENCED_NAME='FN_GET_REPORT_USER_COLUMNS' ORDER BY 2")
show("PK/UK COLS", "SELECT C.TABLE_NAME, C.CONSTRAINT_TYPE, C.CONSTRAINT_NAME, LISTAGG(CC.COLUMN_NAME,',') WITHIN GROUP (ORDER BY CC.POSITION) COLS FROM ALL_CONSTRAINTS C JOIN ALL_CONS_COLUMNS CC ON CC.OWNER=C.OWNER AND CC.CONSTRAINT_NAME=C.CONSTRAINT_NAME WHERE C.OWNER='SCM_MGR' AND C.CONSTRAINT_TYPE IN ('P','U') AND C.TABLE_NAME IN ('SCM_ADM_MNU_M','SCM_ADM_API_M','SCM_ADM_MNU_BTN_MPG_M','SCM_ADM_PROC_M','SCM_ADM_USER_GR_MNU_MPG_M','SCM_ADM_USER_GR_MNU_BTN_MPG_M','SCM_MST_SHEET_COLUMNS','SCM_MST_SHEET_MEASURE','SCM_ADM_MSG_M','SCM_ADM_CMBO_SQL_M','SCM_ADM_PROGRAM_M') GROUP BY C.TABLE_NAME, C.CONSTRAINT_TYPE, C.CONSTRAINT_NAME ORDER BY 1")
show("MNU_M", "SELECT * FROM SCM_ADM_MNU_M WHERE MNU_ID='SCP0100'")
show("MNU_M parent", "SELECT M.* FROM SCM_ADM_MNU_M M WHERE M.MNU_ID IN (SELECT UPPER_MNU_ID FROM SCM_ADM_MNU_M WHERE MNU_ID='SCP0100')")
show("PROGRAM_M", "SELECT * FROM SCM_ADM_PROGRAM_M WHERE PROGRAM_ID='SCP0100'")
show("API_M", "SELECT * FROM SCM_ADM_API_M WHERE API_ID LIKE 'SCP0100%' OR API_ID IN (SELECT API_ID FROM SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID='SCP0100') ORDER BY API_ID")
show("BTN_MPG", "SELECT * FROM SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID='SCP0100' ORDER BY SHT_NM, MNU_BTN_CD")
show("PROC_M", "SELECT PROC_NM,COL_NM,COL_TP_CD,SORT_ORD,CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE FROM SCM_ADM_PROC_M WHERE PROC_NM LIKE 'PKG_SCP0100.%' ORDER BY PROC_NM, SORT_ORD")
show("GR_MNU", "SELECT * FROM SCM_ADM_USER_GR_MNU_MPG_M WHERE MNU_ID='SCP0100' ORDER BY 1")
show("GR_BTN summary", "SELECT USER_GR_ID, COUNT(*) CNT, MIN(CREATION_DATE) MIN_CRE, MAX(LAST_UPDATE_DATE) MAX_UPD, LISTAGG(DISTINCT CREATED_BY,',') CB FROM SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE MNU_ID='SCP0100' GROUP BY USER_GR_ID ORDER BY 1")
show("SHEET_COLUMNS summary", "SELECT SHEET_NAME, NVL(DIVISION_ID,'(null)') DIV, COUNT(*) CNT, MIN(CREATION_DATE) MIN_CRE, MAX(LAST_UPDATE_DATE) MAX_UPD, LISTAGG(DISTINCT CREATED_BY,',') CB, LISTAGG(DISTINCT LAST_UPDATED_BY,',') UB FROM SCM_MST_SHEET_COLUMNS WHERE PROGRAM_ID='SCP0100' GROUP BY SHEET_NAME, DIVISION_ID ORDER BY 1,2")
show("SHEET_MEASURE summary", "SELECT SHEET_NAME, COUNT(*) CNT, MIN(CREATION_DATE) MIN_CRE, MAX(LAST_UPDATE_DATE) MAX_UPD FROM SCM_MST_SHEET_MEASURE WHERE PROGRAM_ID='SCP0100' GROUP BY SHEET_NAME")
show("MSG_M SCP0100", "SELECT MSG_ID,LANG_CD,MSG_TP_CD,MSG_NM,CREATED_BY,CREATION_DATE,LAST_UPDATED_BY,LAST_UPDATE_DATE FROM SCM_ADM_MSG_M WHERE MSG_ID LIKE '%SCP0100%' ORDER BY 1,2")
show("TITLESET_USER summary", "SELECT COUNT(*) CNT, COUNT(DISTINCT USER_ID) USERS, MIN(CREATION_DATE), MAX(LAST_UPDATE_DATE) FROM SCM_MST_TITLESET_USER WHERE PROGRAM_ID='SCP0100'")
show("MSG_M cols", "SELECT COLUMN_NAME,DATA_TYPE,DATA_LENGTH,NULLABLE,DATA_DEFAULT FROM ALL_TAB_COLUMNS WHERE OWNER='SCM_MGR' AND TABLE_NAME='SCM_ADM_MSG_M' ORDER BY COLUMN_ID")
